window.docContents[61].resolve({"/#Cvc___lean----High-Level-API-for-CVC5":{"contents":"Cvc.lean is a high-level Lean 4 API for the cvc5 SMT solver, built on top of the\nlean-cvc5 Lean library. It adds a lot of quality of life features and strives to\nprovide strong static guarantees. The following section of this manual present the library in\ndetails.\n\nThe Overview section showcases various features of cvc.lean to give an overview for\nnewcomers to survey quickly. The rest of this document goes over the technical details needed to\nunderstand and use cvc.lean properly.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Cvc.lean -- High-Level API for CVC5","id":"/#Cvc___lean----High-Level-API-for-CVC5"}});